python3 -c "
with open('/root/weo_data.xls', 'rb') as f:
    raw = f.read()
text = raw.decode('utf-16')
lines = text.split('\n')

# Get header to find year columns
header = lines[0].split('\t')
year_cols = {}
for i, h in enumerate(header):
    h = h.strip()
    if h.isdigit() and 2020 <= int(h) <= 2029:
        year_cols[h] = i

print('Year columns:', year_cols)

# Find all Georgia rows with needed indicators
indicators = ['NGDP_RPCH', 'NGDPD', 'NGDP_D', 'PPPGDP', 'LP']
for line in lines:
    parts = line.split('\t')
    if len(parts) > 5 and parts[3].strip() == 'Georgia' and parts[2].strip() in indicators:
        subj = parts[2].strip()
        desc = parts[4].strip()
        units = parts[6].strip()
        scale = parts[7].strip()
        vals = {}
        for year, col in year_cols.items():
            if col < len(parts):
                vals[year] = parts[col].strip()
        print(f'{subj} | {desc[:60]} | {units} | {scale}')
        for y in sorted(vals.keys()):
            print(f'  {y}: {vals[y]}')
"
